  let cost: number;
  if (weight <= 1) cost = intl ? 15 : 5;
  else if (weight <= 5) cost = intl ? 30 : 10;
  else cost = intl ? 60 : 20;
  if (express === "yes") cost *= 2;
  console.log(cost.toFixed(2));
}

