for (let d = 1; d <= n; d++) {
  if (n % d === 0) divisors++;
}
const isPrime = n >= 2 && divisors === 2;
let digits = 0;
let rest = n;
while (rest > 0) {
  digits++;
  rest = Math.trunc(rest / 10);
}
console.log(sum);
console.log(divisors);
console.log(isPrime);
console.log(digits);

