    console.log("invalid");
    continue;
  }
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const here = value[s[i]];
    const next = i + 1 < s.length ? value[s[i + 1]] : 0;
    total += here < next ? -here : here;
  }
  console.log(total);
}

