import java.util.*;

public class Main {
    static int[] a;
    static int lo;
    static int hi;
    static long sum = 0;
    static int count = 0;

    static void walk(int i) {
        if (i >= a.length || a[i] == -1) return;
        int v = a[i];
        if (v > lo) walk(2 * i + 1);
        if (v >= lo && v <= hi) {
            sum += v;
            count++;
        }
        if (v < hi) walk(2 * i + 2);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        a = new int[n];
        for (int i = 0; i < n; i++) a[i] = sc.nextInt();
        lo = sc.nextInt();
        hi = sc.nextInt();
